sys_script_include.script:
var returnFilter = Class.create();
returnFilter.prototype = {
    initialize: function () {},

    getFilter: function () {
        // Hole die Firma des aktuell eingeloggten Benutzers
        var grUser = new GlideRecord('sys_user');
        grUser.get(gs.getUserID());
        var company = grUser.getValue('company'); // Die sys_id der Firma

        // Prüfen, ob die Firma existiert
        if (!company) {
            gs.info('No company found for the user.');
            return ''; // Kein Filter, wenn keine Firma vorhanden ist
        }

        // Filter erstellen
        var filter = 'company=' + company;
        gs.info('Generated Filter: ' + filter);

        return filter;
    },

    type: 'returnFilter'
};
